command:
godot --headless --path godot/station_trial --fixed-fps 60 --script res://verify_trial.gd
for preset in Windows Linux Web; do
  case "$preset" in
    Windows) name=windows/RVA-Night-Shift.exe ;;
    Linux) name=linux/RVA-Night-Shift.x86_64 ;;
    Web) name=web/index.html ;;
  esac
  godot --headless --path godot/station_trial --export-release "$preset" "$PWD/outputs/godot-trial/$name" > "outputs/export-godot-$preset.log" 2>&1 || { tail -20 "outputs/export-godot-$preset.log"; exit 1; }
  echo "PASS: Created $preset release."
done
outputs/godot-trial/linux/RVA-Night-Shift.x86_64 --headless --audio-driver Dummy --quit-after 30
file outputs/godot-trial/windows/RVA-Night-Shift.exe
